import React, { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, Image, StyleSheet, ScrollView, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useLocalSearchParams } from 'expo-router';
import { signOut } from 'firebase/auth';
import { collection, query, orderBy, limit, onSnapshot, doc, updateDoc, arrayUnion } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from '../constants/theme';
import { AccountSwitcherModal, SelectMoreModal, NewChatModal, NoteModal } from '../constants/DmModals';
import { DmChatRoom } from '../constants/DmChatRoom';
import { DmRequestsView } from '../constants/DmRequestsView';

export default function MessagesScreen() {
  const params = useLocalSearchParams<{ uid?: string; name?: string }>();
    const { c } = useTheme();
      const myUid = auth.currentUser?.uid || '';
        const [me, setMe] = useState<any>(null);
          const [users, setUsers] = useState<any[]>([]);
            const [convos, setConvos] = useState<Record<string, any>>({});
              const [accounts, setAccounts] = useState<any[]>([]);
                const [tab, setTab] = useState<'all' | 'primary' | 'general'>('all');
                  const [inReq, setInReq] = useState(false);
                    const [spamView, setSpamView] = useState(false);
                      const [targetUid, setTargetUid] = useState(params.uid || '');
                        const [targetName, setTargetName] = useState(params.name || 'Chat');
                          const [msgs, setMsgs] = useState<any[]>([]);
                            const [selectMode, setSelectMode] = useState(false);
                              const [selected, setSelected] = useState<string[]>([]);
                                const [modals, setModals] = useState({ menu: false, acc: false, more: false, newChat: false, note: false });

                                  useEffect(() => { if (params.uid) setTargetUid(params.uid); if (params.name) setTargetName(params.name); }, [params.uid, params.name]);

                                    useEffect(() => {
                                        const u1 = onSnapshot(collection(db, 'users'), (s) => setUsers(s.docs.map((d) => ({ id: d.id, ...d.data() })).filter((u) => u.id !== myUid)));
                                            const u2 = myUid ? onSnapshot(doc(db, 'users', myUid), (s) => {
                                                  if (!s.exists()) return;
                                                        const d = s.data(); setMe(d);
                                                              AsyncStorage.getItem('flevora_accounts').then((raw) => {
                                                                      const next = [{ uid: myUid, username: d.username, photoUrl: d.photoUrl }, ...(raw ? JSON.parse(raw) : []).filter((a: any) => a.uid !== myUid)].slice(0, 5);
                                                                              setAccounts(next); AsyncStorage.setItem('flevora_accounts', JSON.stringify(next));
                                                                                    });
                                                                                        }) : () => {};
                                                                                            const u3 = onSnapshot(collection(db, 'conversations'), (s) => {
                                                                                                  const m: Record<string, any> = {}; s.docs.forEach((d) => { m[d.id] = d.data(); }); setConvos(m);
                                                                                                      });
                                                                                                          return () => { u1(); u2(); u3(); };
                                                                                                            }, [myUid]);

                                                                                                              useEffect(() => {
                                                                                                                  if (!targetUid || !myUid) return;
                                                                                                                      const chatId = [myUid, targetUid].sort().join('_');
                                                                                                                          return onSnapshot(query(collection(db, 'conversations', chatId, 'messages'), orderBy('createdAt', 'desc'), limit(40)), (s) => {
                                                                                                                                setMsgs(s.docs.map((d) => ({ id: d.id, ...d.data() })));
                                                                                                                                    });
                                                                                                                                      }, [targetUid, myUid]);

                                                                                                                                        const isOnline = (u: any) => u?.isOnline || (u?.lastSeen?.toDate ? Date.now() - u.lastSeen.toDate().getTime() < 300000 : false);
                                                                                                                                          const cats = me?.chatCategories || {}, hidden = me?.hiddenChats || [], spam = me?.spamChats || [], following = me?.following || [];

                                                                                                                                            const inboxUsers = users.filter((u) => {
                                                                                                                                                if (hidden.includes(u.id)) return false;
                                                                                                                                                    if (inReq && spamView) return spam.includes(u.id);
                                                                                                                                                        if (spam.includes(u.id)) return false;
                                                                                                                                                            const isReq = !!convos[[myUid, u.id].sort().join('_')] && !following.includes(u.id) && !cats[u.id];
                                                                                                                                                                if (inReq) return isReq;
                                                                                                                                                                    if (isReq) return false;
                                                                                                                                                                        const cat = cats[u.id] || 'primary';
                                                                                                                                                                            return tab === 'all' || cat === tab;
                                                                                                                                                                              });

                                                                                                                                                                                const handleMore = async (key: string) => {
                                                                                                                                                                                    if (!myUid || !selected.length) return;
                                                                                                                                                                                        const upd: any = {};
                                                                                                                                                                                            selected.forEach((uid) => {
                                                                                                                                                                                                  if (key === 'move') upd[`chatCategories.${uid}`] = cats[uid] === 'general' ? 'primary' : 'general';
                                                                                                                                                                                                        if (key === 'unread') upd[`unreadChats.${uid}`] = true;
                                                                                                                                                                                                              if (key === 'followup') upd[`followUpChats.${uid}`] = true;
                                                                                                                                                                                                                    if (key === 'muteMsg') upd[`mutedMsgChats.${uid}`] = true;
                                                                                                                                                                                                                          if (key === 'muteCall') upd[`mutedCallChats.${uid}`] = true;
                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                  if (key === 'block') upd.blockedUsers = arrayUnion(...selected);
                                                                                                                                                                                                                                      await updateDoc(doc(db, 'users', myUid), upd);
                                                                                                                                                                                                                                          setSelectMode(false); setSelected([]);
                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                              if (targetUid) {
                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                        <DmChatRoom
                                                                                                                                                                                                                                                                myUid={myUid} me={me} targetUid={targetUid} targetName={targetName} otherUser={users.find((u) => u.id === targetUid)} msgs={msgs} c={c}
                                                                                                                                                                                                                                                                        onBack={() => setTargetUid('')} labelText={me?.followUpChats?.[targetUid] ? 'Follow up' : (cats[targetUid] || 'primary')}
                                                                                                                                                                                                                                                                                onToggleLabel={() => updateDoc(doc(db, 'users', myUid), { [`chatCategories.${targetUid}`]: cats[targetUid] === 'general' ? 'primary' : 'general' })}
                                                                                                                                                                                                                                                                                        onForward={() => Alert.alert('Forward', 'Pick a user from inbox.', [{ text: 'OK', onPress: () => setTargetUid('') }])}
                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                      if (inReq) {
                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                <DmRequestsView
                                                                                                                                                                                                                                                                                                                        users={inboxUsers} spamCount={spam.length} spamView={spamView} setSpamView={setSpamView} c={c}
                                                                                                                                                                                                                                                                                                                                onBack={() => { setInReq(false); setSpamView(false); }}
                                                                                                                                                                                                                                                                                                                                        onOpen={(u: any) => { setTargetUid(u.id); setTargetName(u.username); }}
                                                                                                                                                                                                                                                                                                                                                onAccept={(uid: string) => updateDoc(doc(db, 'users', myUid), { [`chatCategories.${uid}`]: 'primary' })}
                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                  <View style={{ flex: 1, backgroundColor: c.background }}>
                                                                                                                                                                                                                                                                                                                                                                        <View style={s.hdr}>
                                                                                                                                                                                                                                                                                                                                                                                {selectMode ? (
                                                                                                                                                                                                                                                                                                                                                                                          <><View style={{ flex: 1, alignItems: 'center' }}><Text style={[s.hTitle, { color: c.text }]}>{selected.length} selected</Text></View><TouchableOpacity onPress={() => { setSelectMode(false); setSelected([]); }}><Ionicons name="close" size={26} color={c.text} /></TouchableOpacity></>
                                                                                                                                                                                                                                                                                                                                                                                                  ) : (
                                                                                                                                                                                                                                                                                                                                                                                                            <><View style={{ width: 52 }} /><TouchableOpacity style={s.drop} onPress={() => setModals({ ...modals, acc: true })}><Text style={[s.hTitle, { color: c.text }]}>{me?.username || 'Username'}</Text><Ionicons name="chevron-down" size={18} color={c.text} /></TouchableOpacity><View style={{ flexDirection: 'row', gap: 14 }}><TouchableOpacity onPress={() => setModals({ ...modals, menu: !modals.menu })}><Ionicons name="ellipsis-horizontal" size={22} color={c.text} /></TouchableOpacity><TouchableOpacity onPress={() => setModals({ ...modals, newChat: true })}><Ionicons name="create-outline" size={22} color={c.text} /></TouchableOpacity></View></>
                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                          </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                {modals.menu && <TouchableOpacity style={[s.popMenu, { backgroundColor: c.background }]} onPress={() => { setModals({ ...modals, menu: false }); setSelectMode(true); }}><Ionicons name="list-outline" size={20} color={c.text} /><Text style={{ fontWeight: '600', color: c.text, marginLeft: 10 }}>Select chats</Text></TouchableOpacity>}

                                                                                                                                                                                                                                                                                                                                                                                                                                      <View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.actRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={s.actItem} onPress={() => setModals({ ...modals, note: true })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={[s.noteBbl, { backgroundColor: c.card }]}><Text style={{ fontSize: 10, color: c.muted }} numberOfLines={2}>{me?.note || 'Your thoughts\ngo here...'}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {me?.photoUrl ? <Image source={{ uri: me.photoUrl }} style={s.actAv} /> : <View style={[s.actAv, s.ph]}><Ionicons name="person" size={24} color="#fff" /></View>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{ fontSize: 11, color: c.muted, marginTop: 4 }}>Your note</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {users.filter(isOnline).map((u) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity key={u.id} style={s.actItem} onPress={() => { setTargetUid(u.id); setTargetName(u.username); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={{ position: 'relative', marginTop: 18 }}>{u.photoUrl ? <Image source={{ uri: u.photoUrl }} style={s.actAv} /> : <View style={[s.actAv, s.ph]}><Ionicons name="person" size={24} color="#fff" /></View>}<View style={s.dot} /></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ fontSize: 11, color: c.text, marginTop: 4, maxWidth: 64 }} numberOfLines={1}>{u.username}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </ScrollView></View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={s.tabsRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {(['all', 'primary', 'general'] as const).map((t) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity key={t} onPress={() => setTab(t)} style={[s.chip, { backgroundColor: tab === t ? '#E0E7FF' : c.input }]}><Text style={{ fontSize: 13, fontWeight: '600', color: tab === t ? '#4338CA' : c.text }}>{t[0].toUpperCase() + t.slice(1)}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => setInReq(true)} style={[s.chip, { backgroundColor: c.input }]}><Text style={{ fontSize: 13, fontWeight: '600', color: c.text }}>Requests ›</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <FlatList data={inboxUsers} keyExtractor={(i) => i.id} renderItem={({ item }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const cv = convos[[myUid, item.id].sort().join('_')], isSel = selected.includes(item.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const toggle = () => setSelected((p) => (p.includes(item.id) ? p.filter((x) => x !== item.id) : [...p, item.id]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={s.row} onPress={() => (selectMode ? toggle() : (setTargetUid(item.id), setTargetName(item.username)))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {selectMode && <Ionicons name={isSel ? 'checkbox' : 'square-outline'} size={22} color={isSel ? c.text : c.muted} style={{ marginRight: 6 }} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={{ position: 'relative' }}>{item.photoUrl ? <Image source={{ uri: item.photoUrl }} style={s.av} /> : <View style={[s.av, s.ph]}><Ionicons name="person" size={20} color="#fff" /></View>}{isOnline(item) && <View style={s.dot} />}</View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={{ flex: 1 }}><Text style={{ fontSize: 15, fontWeight: '600', color: c.text }}>{item.username}</Text><Text style={{ fontSize: 13, color: c.muted }} numberOfLines={1}>{cv?.lastMessage || (isOnline(item) ? 'Active now' : 'Tap to chat')}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {me?.unreadChats?.[item.id] && <View style={s.uDot} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }} />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {selectMode && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={[s.selBar, { backgroundColor: c.background, borderTopColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity onPress={() => selected.length && setModals({ ...modals, more: true })}><Text style={{ fontWeight: '600', color: selected.length ? c.text : c.muted }}>More</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity disabled={selected.length !== 1} onPress={() => { const u = users.find((x) => x.id === selected[0]); setSelectMode(false); setSelected([]); if (u) { setTargetUid(u.id); setTargetName(u.username); } }}><Text style={{ fontWeight: '600', color: selected.length === 1 ? c.text : c.muted }}>Reply ({selected.length === 1 ? 1 : 0})</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity onPress={async () => { if (!selected.length) return; await updateDoc(doc(db, 'users', myUid), { hiddenChats: arrayUnion(...selected) }); setSelectMode(false); setSelected([]); }}><Text style={{ fontWeight: '600', color: selected.length ? '#EF4444' : c.muted }}>Delete ({selected.length})</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <AccountSwitcherModal visible={modals.acc} onClose={() => setModals({ ...modals, acc: false })} accounts={accounts} currentUid={myUid} onAddAccount={() => signOut(auth)} c={c} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <SelectMoreModal visible={modals.more} onClose={() => setModals({ ...modals, more: false })} onAction={handleMore} isGeneral={selected.length === 1 && cats[selected[0]] === 'general'} c={c} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <NewChatModal visible={modals.newChat} onClose={() => setModals({ ...modals, newChat: false })} users={users} onPick={(u: any) => { setTargetUid(u.id); setTargetName(u.username); }} c={c} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <NoteModal visible={modals.note} onClose={() => setModals({ ...modals, note: false })} initialNote={me?.note} onSave={(v: string) => updateDoc(doc(db, 'users', myUid), { note: v })} c={c} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const s = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              hdr: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingTop: 48, paddingBottom: 10, paddingHorizontal: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                hTitle: { fontSize: 18, fontWeight: '700' }, drop: { flexDirection: 'row', alignItems: 'center', gap: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  popMenu: { position: 'absolute', top: 88, right: 16, zIndex: 20, flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 12, borderRadius: 12, elevation: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    actRow: { paddingHorizontal: 14, paddingVertical: 8, gap: 14 }, actItem: { alignItems: 'center', width: 68 }, actAv: { width: 58, height: 58, borderRadius: 29 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      noteBbl: { paddingHorizontal: 8, paddingVertical: 4, borderRadius: 12, marginBottom: -8, zIndex: 2, elevation: 2 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dot: { position: 'absolute', right: 1, bottom: 1, width: 13, height: 13, borderRadius: 7, backgroundColor: '#10B981', borderWidth: 2, borderColor: '#fff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tabsRow: { flexDirection: 'row', paddingHorizontal: 14, paddingVertical: 8, gap: 8 }, chip: { flex: 1, alignItems: 'center', paddingVertical: 7, borderRadius: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            row: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 10, gap: 12 }, av: { width: 50, height: 50, borderRadius: 25 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ph: { backgroundColor: BRAND, alignItems: 'center', justifyContent: 'center' }, uDot: { width: 9, height: 9, borderRadius: 5, backgroundColor: '#3B82F6' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                selBar: { flexDirection: 'row', justifyContent: 'space-around', paddingVertical: 14, borderTopWidth: 0.5 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                